export function validateAlbumExtras(input){
 const fail=()=>{throw Object.assign(Error('album_extra_invalid'),{status:400,display:'نام خدمت، مبلغ معتبر و روش محاسبه را کامل کنید.'})};
 if(!Array.isArray(input)||input.length>60)fail();const names=new Set(),ids=new Set();
 return input.map(row=>{if(!row||typeof row!=='object')fail();const name=String(row.name||'').trim(),raw=String(row.price??'').trim(),price=Number(raw),id=String(row.id||'');if(!name||name.length>90||!raw||!Number.isSafeInteger(price)||price<0||price>9000000000||!['flat','per_spread'].includes(row.pricingMode)||names.has(name.toLocaleLowerCase('fa-IR'))||(id&&ids.has(id)))fail();names.add(name.toLocaleLowerCase('fa-IR'));if(id)ids.add(id);return {id,name,price,pricingMode:row.pricingMode,active:row.active!==false};});
}
export async function saveAlbumExtras({pool,labId,extras,onChanged}){
 const rows=validateAlbumExtras(extras),c=await pool.connect();let released=false;try{await c.query('BEGIN');await c.query('SELECT id FROM labs WHERE id=$1 FOR UPDATE',[labId]);const old=(await c.query('SELECT id,name,price,pricing_mode,active,sort_order FROM lab_album_extras WHERE lab_id=$1 FOR UPDATE',[labId])).rows,owned=new Set(old.map(r=>String(r.id))),keep=[];
 for(let i=0;i<rows.length;i++){const row=rows[i];let q;if(owned.has(row.id)){q=await c.query('UPDATE lab_album_extras SET name=$3,price=$4,pricing_mode=$5,active=$6,sort_order=$7 WHERE id=$1 AND lab_id=$2 RETURNING id',[row.id,labId,row.name,row.price,row.pricingMode,row.active,i]);}else{if(/^[0-9a-f-]{36}$/i.test(row.id))throw Object.assign(Error('album_extra_not_found'),{status:409});q=await c.query('INSERT INTO lab_album_extras(lab_id,name,price,pricing_mode,active,sort_order) VALUES($1,$2,$3,$4,$5,$6) RETURNING id',[labId,row.name,row.price,row.pricingMode,row.active,i]);}keep.push(String(q.rows[0].id));}
 await c.query('DELETE FROM lab_album_extras WHERE lab_id=$1 AND NOT(id=ANY($2::uuid[]))',[labId,keep]);const result=(await c.query('SELECT id,name,price,pricing_mode,active,sort_order FROM lab_album_extras WHERE lab_id=$1 ORDER BY sort_order',[labId])).rows.map(r=>({id:String(r.id),name:r.name,price:Number(r.price),pricingMode:r.pricing_mode,active:r.active,sortOrder:r.sort_order}));await c.query('COMMIT');c.release();released=true;if(onChanged)try{await onChanged(old.map(r=>({id:String(r.id),name:r.name,price:Number(r.price),pricingMode:r.pricing_mode,active:r.active})),result)}catch{console.warn('[album-extras] tariff notification failed after save')}return result;
 }catch(e){await c.query('ROLLBACK');throw e}finally{if(!released)c.release()}
}
